return $input.all().map((item, i) => {
  const xml = Object.entries(item.binary || {}).filter(([, b]) => /\.xml$/i.test(b.fileName || ''));
  return { json: { hasUbl: xml.length === 1, attachmentKey: xml.length === 1 ? xml[0][0] : null,
    manualReason: xml.length === 1 ? null : 'Provide exactly one UBL XML attachment. PDF extraction and multiple invoices are not supported.' },
    binary: item.binary, pairedItem: { item: i } };
});

try {
  const bytes = await this.helpers.getBinaryDataBuffer(0, $input.first().json.attachmentKey);
  const xml = bytes.toString('utf8');
  if (bytes.length > 262144 || /<!DOCTYPE|<!ENTITY|\u0000|\uFFFD/i.test(xml)) throw new Error('Only UTF-8 UBL without DTD/entities, up to 256 KiB, is supported');
  return [{ json: { xml } }];
} catch (error) {
  return [{ json: { xml: '<Rejected/>', inputError: String(error.message) } }];
}

// Deliberately narrow v1: canonical UBL prefixes, EUR, one credit transfer, no adjustments.
try {
  const root = $input.first().json;
  const one = (obj, key, optional = false) => {
    const a = obj?.[key];
    if (optional && a === undefined) return undefined;
    if (!Array.isArray(a) || a.length !== 1) throw new Error(`Expected exactly one ${key}`);
    return a[0];
  };
  const text = (obj, key, optional = false) => {
    const v = one(obj, key, optional);
    if (v === undefined) return undefined;
    const s = typeof v === 'object' ? v._ : v;
    if (typeof s !== 'string' || !s.trim()) throw new Error(`Missing text: ${key}`);
    return s.trim();
  };
  const number = (obj, key) => {
    const s = text(obj, key);
    if (!/^\d+(\.\d{1,2})?$/.test(s) || Number(s) > 100000000) throw new Error(`Unsupported decimal: ${key}`);
    return Number(s);
  };
  const r = root?.Invoice;
  if (!r || r.$?.xmlns !== 'urn:oasis:names:specification:ubl:schema:xsd:Invoice-2' || r.$?.['xmlns:cac'] !== 'urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2' || r.$?.['xmlns:cbc'] !== 'urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2') throw new Error('Canonical UBL Invoice namespaces required');
  let accounts = 0;
  const walk = (v) => {
    if (!v || typeof v !== 'object') return;
    for (const [k, child] of Object.entries(v)) {
      if (/AllowanceCharge|PrepaidPayment|PayeeParty|PaymentTerms|AlternativeCurrency|AccountingCost|InvoicePeriod|BaseQuantity|PayableRoundingAmount|PrepaidAmount/.test(k)) throw new Error(`Unsupported v1 field: ${k}`);
      if (k === 'cac:PayeeFinancialAccount') accounts += child.length;
      if (k === '$' && child.currencyID && child.currencyID !== 'EUR') throw new Error('Mixed currency');
      walk(child);
    }
  };
  walk(r);
  if (accounts !== 1 || text(r, 'cbc:InvoiceTypeCode') !== '380' || text(r, 'cbc:DocumentCurrencyCode') !== 'EUR') throw new Error('Only a EUR invoice with one payee account is supported');
  const party = (key) => {
    const p = one(one(r, key), 'cac:Party');
    const addr = one(p, 'cac:PostalAddress');
    const endpoint = one(p, 'cbc:EndpointID', true);
    if (endpoint !== undefined && !endpoint.$?.schemeID) throw new Error('Peppol endpoint scheme required');
    return { name: text(one(p, 'cac:PartyName'), 'cbc:Name'), countryCode: text(one(addr, 'cac:Country'), 'cbc:IdentificationCode'), vatId: text(one(p, 'cac:PartyTaxScheme'), 'cbc:CompanyID'), street: text(addr, 'cbc:StreetName'), city: text(addr, 'cbc:CityName'), postalZone: text(addr, 'cbc:PostalZone'), endpointId: text(p, 'cbc:EndpointID', true), endpointScheme: endpoint?.$?.schemeID };
  };
  const payment = one(r, 'cac:PaymentMeans');
  if (text(payment, 'cbc:PaymentMeansCode') !== '30') throw new Error('Only credit transfer (30) is supported');
  const iban = text(one(payment, 'cac:PayeeFinancialAccount'), 'cbc:ID').replace(/ /g, '').toUpperCase();
  const monetary = one(r, 'cac:LegalMonetaryTotal');
  const total = number(monetary, 'cbc:TaxInclusiveAmount');
  if (total <= 0 || total !== number(monetary, 'cbc:PayableAmount')) throw new Error('Payable amount must equal positive tax-inclusive total');
  const rawLines = r['cac:InvoiceLine'];
  if (!Array.isArray(rawLines) || !rawLines.length || rawLines.length > 100) throw new Error('Expected 1-100 lines');
  const lines = rawLines.map(l => {
    const item = one(l, 'cac:Item'), tax = one(item, 'cac:ClassifiedTaxCategory');
    const quantity = number(l, 'cbc:InvoicedQuantity'), unitPrice = number(one(l, 'cac:Price'), 'cbc:PriceAmount');
    if (Math.round(quantity * unitPrice * 100) !== Math.round(number(l, 'cbc:LineExtensionAmount') * 100)) throw new Error('Line amount mismatch');
    return { description: text(item, 'cbc:Name'), quantity, unitPrice, vatPercent: number(tax, 'cbc:Percent'), taxCategory: text(tax, 'cbc:ID'), unitCode: one(l, 'cbc:InvoicedQuantity').$?.unitCode || 'EA' };
  });
  const net = Math.round(lines.reduce((a, l) => a + Math.round(l.quantity * l.unitPrice * 100), 0));
  const tax = Math.round(number(one(r, 'cac:TaxTotal'), 'cbc:TaxAmount') * 100);
  if (net !== Math.round(number(monetary, 'cbc:LineExtensionAmount') * 100) || net !== Math.round(number(monetary, 'cbc:TaxExclusiveAmount') * 100) || net + tax !== Math.round(total * 100)) throw new Error('Invoice totals mismatch');
  const invoice = { invoiceNumber: text(r, 'cbc:ID'), issueDate: text(r, 'cbc:IssueDate'), dueDate: text(r, 'cbc:DueDate'), currency: 'EUR', buyerReference: text(r, 'cbc:BuyerReference', true), supplier: party('cac:AccountingSupplierParty'), customer: party('cac:AccountingCustomerParty'), lines, iban, payment: { iban }, totalIncludingVat: total };
  return [{ json: { invoice, supplierKey: invoice.supplier.vatId, inputError: null } }];
} catch (e) {
  return [{ json: { inputError: String(e.message), supplierKey: '__INVALID_INVOICE__' } }];
}

const base = $('Operator settings').first().json;
const rows = $input.all().map(i => i.json);
const row = rows[0];
const valid = rows.length === 1 && row.supplierKey === base.supplierKey && typeof row.ibanOnFile === 'string' && /^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(row.ibanOnFile);
return [{ json: { ...base, ibanOnFile: valid ? row.ibanOnFile : '', supplierError: valid ? null : 'Missing, ambiguous or invalid trusted supplier record; do not pay.' } }];

const base = $('Bind trusted supplier').first().json;
const response = $input.first().json;
let paymentVerdict = 'unavailable', paymentError = null, payment = null;
try {
  if (response.statusCode !== 200 || response.error) throw new Error('Payment check HTTP failure');
  const rpc = typeof response.data === 'string' ? JSON.parse(response.data) : response.data;
  if (rpc?.jsonrpc !== '2.0' || rpc.id !== 'payment-change' || rpc.error || rpc.result?.isError !== false) throw new Error('No valid JSON-RPC verdict');
  const content = rpc.result.structuredContent;
  if (content?.kind !== 'payment_change_check' || !['no_change', 'verify_first', 'stop', 'invalid_new_account'].includes(content.data?.verdict)) throw new Error('Unknown payment verdict');
  payment = content.data;
  if (['no_change', 'verify_first'].includes(payment.verdict)) {
    const clean = s => typeof s === 'string' ? s.replace(/ /g, '') : '';
    if (payment.newAccount?.status !== 'valid' || clean(payment.newAccount.iban) !== base.invoice?.iban || payment.accountOnFile?.status !== 'valid' || clean(payment.accountOnFile.iban) !== base.ibanOnFile) throw new Error('Account binding mismatch');
  }
  paymentVerdict = payment.verdict;
} catch (error) { paymentError = String(error.message); }
return [{ json: { ...base, paymentVerdict, paymentError, payment, paymentResponse: response } }];

const base = $('Read payment verdict').first().json;
const response = $input.first().json;
let review = null, reviewUsable = false, reviewError = null;
try {
  if (response.statusCode !== 200 || response.error) throw new Error('Invoice review HTTP failure');
  const body = typeof response.data === 'string' ? JSON.parse(response.data) : response.data;
  review = body?.review;
  if (!review || review.invoiceNumber !== base.invoice?.invoiceNumber || review.readyToSend !== true || typeof review.hasUnknowns !== 'boolean' || !Array.isArray(review.checks) || !Array.isArray(review.findings)) throw new Error('Missing, blocked or mismatched review');
  for (const id of ['structure', 'arithmetic', 'payment_details', 'peppol']) {
    const checks = review.checks.filter(c => c.id === id);
    if (checks.length !== 1 || checks[0].status !== 'pass' || checks[0].source !== 'local') throw new Error(`No passing local check: ${id}`);
  }
  if (review.findings.some(f => f.severity === 'blocker') || review.checks.some(c => c.status === 'fail') || Number(review.totals?.payableAmount) !== base.invoice.totalIncludingVat) throw new Error('Blocking finding or amount mismatch');
  reviewUsable = true;
} catch (error) { reviewError = String(error.message); }
return [{ json: { ...base, review, reviewUsable, reviewError, reviewResponse: response } }];

const base = $('Read review verdict').first().json;
const rows = $input.all().map(i => i.json);
const skipped = rows.length === 1 && rows[0].reviewUsable !== undefined;
const optionalVat = skipped ? {status:'skipped',reason:'Optional credential-backed VAT node is disabled'} : {status:rows.length === 1 && rows[0].status === 'valid' ? 'valid' : 'not_passed',rows};
const checksPermitExport = !base.inputError && !base.supplierError && ['verify_first','no_change'].includes(base.paymentVerdict) && base.reviewUsable === true && ['skipped','valid'].includes(optionalVat.status);
const summary = { label:checksPermitExport ? 'HUMAN VERIFICATION REQUIRED' : 'DO NOT PAY - no usable verdict; resolve and rerun', invoice:base.invoice, ibanOnFile:base.ibanOnFile, paymentVerdict:base.paymentVerdict, payment:base.payment, invoiceChecks:base.review?.checks, findings:base.review?.findings, hasUnknowns:base.review?.hasUnknowns ?? true, optionalVat, errors:[base.inputError,base.supplierError,base.paymentError,base.reviewError].filter(Boolean), instructions:'Every invoice requires human approval. For verify_first: call a trusted number already on file, confirm account ownership and the exact IBAN independently, record the callback and obtain a second-person approval. Approval does not fix missing/failed checks. Skipped/unknown VAT is NOT a pass. This creates proposals only, not a payment or ledger posting.' };
const escape = s => s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
return [{json:{...base,optionalVat,checksPermitExport,summaryHtml:`<pre>${escape(JSON.stringify(summary,null,2))}</pre>`}}];

const base = $('Approval summary').first().json;
const approval = $input.first().json.data;
const exportAllowed = approval?.approved === true && base.checksPermitExport === true;
return [{json:{...base,approval:approval || {approved:false,reason:'No response / expired'},exportAllowed,outcome:exportAllowed ? 'approved_proposal' : 'rejected_or_held'}}];

const state = $input.first().json;
if (state.exportAllowed !== true || state.checksPermitExport !== true || state.approval?.approved !== true) throw new Error('No approved, checked invoice');
const inv = state.invoice, op = state.operator;
const ibanValid = (s) => {
  if (typeof s !== 'string' || !/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(s)) return false;
  const digits = (s.slice(4) + s.slice(0, 4)).replace(/[A-Z]/g, c => String(c.charCodeAt(0) - 55));
  let remainder = 0;
  for (const c of digits) remainder = (remainder * 10 + Number(c)) % 97;
  return remainder === 1;
};
const amount = inv?.totalIncludingVat;
if (!op || !op.debtorName || op.debtorName.length > 70 || !ibanValid(op.debtorIban) || !/^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$/.test(op.debtorBic || '') || !/^\d{4}-\d{2}-\d{2}$/.test(op.executionDate || '') || new Date(op.executionDate).toISOString().slice(0,10) !== op.executionDate) throw new Error('Configure trusted debtor name, IBAN, BIC and execution date');
if (inv.currency !== 'EUR' || !ibanValid(inv.iban) || !Number.isFinite(amount) || amount <= 0 || amount > 100000000 || Math.abs(amount * 100 - Math.round(amount * 100)) > 0.00001) throw new Error('Invalid payment data');
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const now = new Date().toISOString(), id = `AP-${$execution.id}`.slice(0,35), sum = amount.toFixed(2);
const xml = `<?xml version="1.0" encoding="UTF-8"?>
<Document xmlns="urn:iso:std:iso:20022:tech:xsd:pain.001.001.03"><CstmrCdtTrfInitn>
<GrpHdr><MsgId>${esc(id)}</MsgId><CreDtTm>${now}</CreDtTm><NbOfTxs>1</NbOfTxs><CtrlSum>${sum}</CtrlSum><InitgPty><Nm>${esc(op.debtorName)}</Nm></InitgPty></GrpHdr>
<PmtInf><PmtInfId>${esc(id)}</PmtInfId><PmtMtd>TRF</PmtMtd><NbOfTxs>1</NbOfTxs><CtrlSum>${sum}</CtrlSum><PmtTpInf><SvcLvl><Cd>SEPA</Cd></SvcLvl></PmtTpInf><ReqdExctnDt>${op.executionDate}</ReqdExctnDt><Dbtr><Nm>${esc(op.debtorName)}</Nm></Dbtr><DbtrAcct><Id><IBAN>${op.debtorIban}</IBAN></Id></DbtrAcct><DbtrAgt><FinInstnId><BIC>${op.debtorBic}</BIC></FinInstnId></DbtrAgt><ChrgBr>SLEV</ChrgBr>
<CdtTrfTxInf><PmtId><EndToEndId>${esc(id)}</EndToEndId></PmtId><Amt><InstdAmt Ccy="EUR">${sum}</InstdAmt></Amt><Cdtr><Nm>${esc(inv.supplier.name.slice(0,70))}</Nm></Cdtr><CdtrAcct><Id><IBAN>${inv.iban}</IBAN></Id></CdtrAcct><RmtInf><Ustrd>${esc(inv.invoiceNumber.slice(0,140))}</Ustrd></RmtInf></CdtTrfTxInf>
</PmtInf></CstmrCdtTrfInitn></Document>`;
const bookingProposal = { kind:'accounts_payable_proposal',posted:false,invoiceNumber:inv.invoiceNumber,supplier:inv.supplier,amount:sum,currency:'EUR',payeeIban:inv.iban,lines:inv.lines,approval:state.approval,executionId:$execution.id,ledgerAccount:null,note:'Not posted or paid. Accountant must choose ledger accounts and tax treatment; bank acceptance is not proven.' };
return [{json:{...state,bookingProposal},binary:{sepa:await this.helpers.prepareBinaryData(Buffer.from(xml),`${id}-pain.001.xml`,'application/xml'),booking:await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(bookingProposal,null,2)),`${id}-booking.json`,'application/json')}}];
